 * SPDX-License-Identifier: Apache-2.0
 *
 * 7x7 convolution, 1 input channel -> 128 output channels, hardwired weights.
 *
 * For every output pixel the chip computes 128 sums, one per filter f:
 *   y[f] = sum over ky,kx in 0..6 of w[f][ky][kx] * x[ky][kx]
 * (128 x 49 = 6272 multiply-accumulates). The weights live in a ROM built from
 * logic (src/weights_rom.v, generated by tools/gen_weights.py) at address
 * f*49 + ky*7 + kx.
 *
 * The host streams the image one column of 7 pixels at a time (top to bottom).
 * Each column shifts into a 7x7 window from the right. Once 7 columns of a row
 * band are loaded, every further column produces one output pixel, so sliding
 * the window one pixel to the right costs only 7 input bytes. Results come out
 * as 128 exact signed 21-bit sums per pixel, in filter order, through a
 * read/ACK handshake.
 *
 * Pins
 *   ui_in[7:0]   PIX       signed 8-bit pixel
 *   uio_in[0]    VALID     PIX is accepted on a rising clk edge while VALID=1
 *   uio_in[1]    START     with VALID: PIX is the top of the first column of a new row band
 *   uio_in[3:2]  BYTE_SEL  0..2: byte of the sign-extended 24-bit result (0 = LSB); 3: filter index
 *   uio_in[4]    ACK       high for one clock: the host has read the result
 *   uio_out[5]   IN_RDY    the column buffer has room for PIX
 *   uio_out[6]   ERR       sticky until reset: PIX sent while IN_RDY=0, or ACK with no result
 *   uio_out[7]   OUT_VALID the result register holds an unread result
 *   uo_out[7:0]  RESULT    byte BYTE_SEL of the result
 */

`default_nettype none

module tt_um_ejborcherding_conv7x7 (
    input  wire [7:0] ui_in,    // Dedicated inputs
    output wire [7:0] uo_out,   // Dedicated outputs
    input  wire [7:0] uio_in,   // IOs: Input path
    output wire [7:0] uio_out,  // IOs: Output path
    output wire [7:0] uio_oe,   // IOs: Enable path (active high: 0=input, 1=output)
    input  wire       ena,      // always 1 when the design is powered, so you can ignore it
    input  wire       clk,      // clock
    input  wire       rst_n     // reset_n - low to reset
);

  // 128 filters x 49 taps = 6272 weights
  localparam integer AW    = 13;  // ROM address bits
  localparam integer ACC_W = 21;  // |sum| <= 49 * 16384 < 2^20

  // ---------------------------------------------------------------- inputs
  wire       in_valid = uio_in[0];
  wire       in_start = uio_in[1];
  wire [1:0] byte_sel = uio_in[3:2];
  wire       in_ack   = uio_in[4];

  // --------------------------------------------- column buffer and window
  reg  [55:0]  col;          // pixel ky of the incoming column at col[8*ky +: 8]
  reg  [2:0]   col_cnt;      // pixels received; 7 = full
  reg          col_new_row;  // the column was begun with START
  reg  [391:0] win;          // pixel (ky, kx) at win[8*(ky*7 + kx) +: 8]
  reg  [2:0]   win_cols;     // columns loaded since the row band began, saturates at 7

  wire col_full = (col_cnt == 3'd7);

  // Shifting: every row moves one column left and the new column enters at kx = 6.
  wire [391:0] win_shifted;
  genvar gy;
  generate
    for (gy = 0; gy < 7; gy = gy + 1) begin : g_row
      assign win_shifted[56*gy +: 56] = {col[8*gy +: 8], win[56*gy + 8 +: 48]};
    end
  endgenerate

  // ----------------------------------------------- engine: stage 0 (issue)
  reg          running;
  reg [5:0]    tap;          // ky*7 + kx
  reg [6:0]    filt;
  reg [AW-1:0] addr;         // filt*49 + tap

  reg [ACC_W-1:0] out_data;
  reg [6:0]       out_filt;
  reg             out_full;
  reg             err;

  wire ack       = in_ack & out_full;
  wire out_free  = ~out_full | ack;
  wire tap_last  = (tap == 6'd48);
  wire filt_last = (filt == 7'd127);

  // The last tap of a filter is held back until the result register can take
  // its sum, so a slow host stalls the engine instead of losing results.
  wire issue     = running & (~tap_last | out_free);
  wire pixel_end = issue & tap_last & filt_last;

  // A full column enters the window once nothing still reads the old window.
  // On the last issue of a pixel the swap happens in the same cycle, so
  // consecutive pixels run back to back.
  wire       shift     = col_full & (~running | pixel_end);
  wire [2:0] cols_next = col_new_row ? 3'd1 : (win_cols == 3'd7) ? 3'd7 : win_cols + 3'd1;
  wire       launch    = shift & (cols_next == 3'd7);

  wire [7:0] rom_w;
  conv_weights weights_rom (
      .addr(addr),
      .w   (rom_w)
  );

  wire [7:0] tap_x = win[8*tap +: 8];

  // ------------------------------------------ stage 1: registered operands
  reg              s1_valid, s1_first, s1_last;
  reg [6:0]        s1_filt;
  reg signed [7:0] s1_w, s1_x;

  // ------------------------------------------------ stage 2: accumulate
  reg signed [ACC_W-1:0] acc;

  wire signed [15:0]      prod     = s1_w * s1_x;
  wire signed [ACC_W-1:0] acc_base = s1_first ? {ACC_W{1'b0}} : acc;
  wire signed [ACC_W-1:0] acc_next = acc_base + {{(ACC_W - 16){prod[15]}}, prod};

  always @(posedge clk) begin
    if (!rst_n) begin
      col_cnt     <= 3'd0;
      col_new_row <= 1'b0;
      win_cols    <= 3'd0;
      running     <= 1'b0;
      tap         <= 6'd0;
      filt        <= 7'd0;
      addr        <= {AW{1'b0}};
      s1_valid    <= 1'b0;
      s1_first    <= 1'b0;
      s1_last     <= 1'b0;
      s1_filt     <= 7'd0;
      s1_w        <= 8'sd0;
      s1_x        <= 8'sd0;
      acc         <= {ACC_W{1'b0}};
      out_data    <= {ACC_W{1'b0}};
      out_filt    <= 7'd0;
      out_full    <= 1'b0;
      err         <= 1'b0;
    end else begin
      // column buffer -> window
      if (shift) begin
        win         <= win_shifted;
        win_cols    <= cols_next;
        col_cnt     <= 3'd0;
        col_new_row <= 1'b0;
      end

      // pixel input; START restarts the column even if it was partly filled
      if (in_valid & in_start) begin
        col[7:0]    <= ui_in;
        col_cnt     <= 3'd1;
        col_new_row <= 1'b1;
      end else if (in_valid & ~col_full) begin
        col[8*col_cnt +: 8] <= ui_in;
        col_cnt             <= col_cnt + 3'd1;
      end

      if ((in_valid & col_full) | (in_ack & ~out_full)) err <= 1'b1;

      // stage 0: walk filt 0..127, tap 0..48
      if (launch) begin
        running <= 1'b1;
        tap     <= 6'd0;
        filt    <= 7'd0;
        addr    <= {AW{1'b0}};
      end else if (issue) begin
        addr <= addr + 1'b1;
        if (tap_last) begin
          tap  <= 6'd0;
          filt <= filt + 1'b1;
          if (filt_last) running <= 1'b0;
        end else begin
          tap <= tap + 1'b1;
        end
      end

      // stage 0 -> stage 1
      s1_valid <= issue;
      if (issue) begin
        s1_w     <= rom_w;
        s1_x     <= tap_x;
        s1_first <= (tap == 6'd0);
        s1_last  <= tap_last;
        s1_filt  <= filt;
      end

      // stage 1 -> stage 2 (an ACK and a new result never land in the same cycle)
      if (ack) out_full <= 1'b0;
      if (s1_valid) begin
        acc <= acc_next;
        if (s1_last) begin
          out_data <= acc_next;
          out_filt <= s1_filt;
          out_full <= 1'b1;
        end
      end
    end
  end

  // ---------------------------------------------------------------- outputs
  wire [23:0] result24 = {{(24 - ACC_W){out_data[ACC_W-1]}}, out_data};

  reg [7:0] out_byte;
  always @(*) begin
    case (byte_sel)
      2'd0:    out_byte = result24[7:0];
      2'd1:    out_byte = result24[15:8];
      2'd2:    out_byte = result24[23:16];
      default: out_byte = {1'b0, out_filt};
    endcase
  end

  assign uo_out  = out_byte;
  assign uio_out = {out_full, err, ~col_full, 5'b0};
  assign uio_oe  = 8'b1110_0000;

  // List all unused inputs to prevent warnings
  wire _unused = &{ena, uio_in[7:5], 1'b0};

endmodule
